const {chromium}=require('playwright'),fs=require('fs'),path=require('path'),assert=require('assert');
(async()=>{const out=process.env.OUTPUT_DIR;fs.mkdirSync(out,{recursive:true});const source=fs.readFileSync('leetcode/691/solution.py','utf8');const b=await chromium.launch({headless:true,executablePath:process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH});try{const c=await b.newContext({permissions:['clipboard-read','clipboard-write']});const p=await c.newPage();await p.goto(process.env.PREVIEW_ROOT+'/leetcode/691/');await p.evaluate(()=>{window.probeWrite=navigator.clipboard.writeText.bind(navigator.clipboard);});const records=[];for(const locale of ['en','zh']){await p.click(`[data-lang=${locale}]`);const sentinel='691-'+locale+'-NOT-SOURCE';await p.evaluate(async sentinel=>{await window.probeWrite(sentinel);navigator.clipboard.writeText=()=>Promise.reject(new Error('intentional fallback probe'));},sentinel);await p.click('#copy');await p.locator('#manualCopy').waitFor({state:'visible'});assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),sentinel);assert.deepEqual(await p.locator('#copyText').evaluate(n=>({focus:document.activeElement===n,start:n.selectionStart,end:n.selectionEnd,value:n.value})),{focus:true,start:0,end:source.length,value:source});const key=process.platform==='darwin'?'Meta+C':'Control+C';await p.keyboard.press(key);assert.equal(await p.evaluate(()=>navigator.clipboard.readText()),source);records.push({locale,key,sentinelVerifiedBeforeKey:true,exactReadback:true,status:await p.locator('#copyStatus').textContent()});}fs.writeFileSync(path.join(out,'fallback-results.json'),JSON.stringify({platform:process.platform,records},null,2)+'\n');console.log(JSON.stringify({fallbackLocales:records.length,result:'pass'}));}finally{await b.close();}})().catch(e=>{console.error(e);process.exitCode=1});
